        map["And?"] = "Et alors ?";
        map["And we feel that we should probably defer to Lady Unterwald's final wishes on this."] = "Et nous pensons devoir nous en remettre aux dernières volontés de Lady Unterwald.";
        map["The best way to do that would be to get a look at her last will and testament."] = "Le meilleur moyen est de consulter son testament.";
        map["You mean the one that her careless attorney lost?"] = "Vous voulez parler de celui que son négligent avocat a égaré ?";
        map["Okay, now who's rubbing it in?"] = "Très bien, et qui remue le couteau dans la plaie maintenant ?";
        map["Now, now. I know tensions are high, but we need to keep our composure."] = "Allons, allons. La tension est palpable, mais gardons notre calme.";
        map["Perhaps you could provide a status report on your efforts, Arthur?"] = "Peut-être pourriez-vous nous faire un rapport sur vos recherches, Arthur ?";
        map["I'm still working to get the last will and testament back."] = "Je remue ciel et terre pour retrouver ce testament.";
        map["While I was looking, I discovered a hidden safe in Lady Unterwald's quarters."] = "En cherchant, j'ai découvert un coffre-fort secret dans les quartiers de Lady Unterwald.";
        map["Is that so?"] = "Vraiment ?";
        map["I don't think we knew about that one, did we?"] = "Nous ignorions son existence, n'est-ce pas ?";
        map["It's sealed shut, but with the right information I think we could get it open."] = "Il est hermétiquement clos, mais avec les bons indices, on devrait pouvoir l'ouvrir.";
        map["It's possible that Lady Unterwald kept a copy of her will inside that safe."] = "Il est fort possible que Lady Unterwald y ait gardé un double de son testament.";
        map["Oh, well that is good news!"] = "Oh, voilà une excellente nouvelle !";
        map["That would certainly save us the headache of coming up with a better plan."] = "Cela nous évitera bien des maux de tête pour échafauder un autre plan.";
        map["Indeed. I think that wraps things up quite neatly then?"] = "Parfaitement. Je pense que tout est réglé comme du papier à musique, non ?";
        map["What do you mean?"] = "Comment ça ?";
        map["Alright, Arthur! Just let us know when you've got that safe open, and we'll take it from there!"] = "Parfait, Arthur ! Faites-nous signe quand vous l'aurez ouvert, et nous prendrons le relais !";
        map["Bu-"] = "Ma...";
        map["Excellent work!"] = "Excellent travail !";
        map["Well, I don't know, do I? This is just the demo."] = "Eh bien, je n'en sais rien, moi ! Ce n'est que la démo !";
        map["Oh, right."] = "Ah, oui, exact.";
        map["UhHh ohH"] = "Ouh là là...";
        map["It's a mouse burrow."] = "C'est un terrier de souris.";

        // Write output TSV
        int count = 0;
        using (var sw = new StreamWriter(@"translations\partitions\c1_b1_french.tsv", false, Encoding.UTF8)) {
            sw.WriteLine("Id\tCharacter\tEnglish\tFrench\tClass\tMethod");
            foreach (var l in lines) {
                var p = l.Split('\t');
                if (p.Length < 6) continue;
                string en = p[2].Trim();
                string fr = "";
                if (map.ContainsKey(en)) {
                    fr = map[en];
                } else {
                    // Fallback to English if not yet mapped
                    fr = en;
                }
                sw.WriteLine(string.Format("{0}\t{1}\t{2}\t{3}\t{4}\t{5}", p[0], p[1], en, fr, p[4], p[5]));
                if (!string.IsNullOrEmpty(fr) && fr != en) count++;
            }
        }
        Console.WriteLine(string.Format("Generated c1_b1_french.tsv: {0} lines translated out of {1}", count, lines.Length));
    }
}
